import { environment } from 'src/environments/environment';
import { Spreadsheet, CellSaveEventArgs } from '@syncfusion/ej2-angular-spreadsheet';

interface CellData {
    Key: string;
    Value: string;
}

interface RowData {
    Data: CellData[];
}

